SELECT ?point ?ts WHERE {
  ?z a ref:Zone ; rdfs:label "Perimeter_mid_ZN_4" .
  ?p ref:hasLocation ?z .
  ?p a brick:AirTemperatureSensor .
  ?p ref:hasTimeseriesId ?ts .
}

SELECT ?point ?ts ?pclass WHERE {
  ?z rdfs:label "Perimeter_mid_ZN_4" .
  ?p ref:hasLocation ?z ; ref:hasTimeseriesId ?ts .
  ?point a ?pclass ; ref:hasTimeseriesId ?ts .
  FILTER(?point = ?p)
}

SELECT ?s ?p WHERE {
  ?p a brick:AirTemperatureSensor ; ref:hasTimeseriesId ?s .
} LIMIT 20

SELECT ?p (STR(?pc) as ?pc) ?s WHERE {
  ?z rdfs:label "Perimeter_mid_ZN_4" .
  ?p ref:hasLocation ?z ; a ?pc ; ref:hasTimeseriesId ?s .
}

SELECT ?p (STR(?pc) as ?pc) WHERE {
  ?z rdfs:label "Perimeter_mid_ZN_4" .
  ?p ref:hasLocation ?z .
  OPTIONAL { ?p a ?pc . }
}

SELECT ?p (STR(?pc) as ?pc) WHERE {
  ?p a brick:AirTemperatureSensor .
} LIMIT 20

